operations:
/* Current choice first; complete original notes remain one voluntary reading surface. */
.milestone-review[data-focus=choice] .milestone-scene{height:auto;min-height:160px;overflow:visible;border-color:#789e8766}
.milestone-review[data-focus=choice] .milestone-scene>.milestone-person{flex-basis:150px;width:150px;height:160px}
.milestone-choice{flex:1;min-width:0;padding:16px 20px;background:linear-gradient(90deg,#103337f5,#103337ce)}
.milestone-review .milestone-choice .milestone-effect{border:0;padding:0;margin:6px 0;font-size:22px;line-height:1.55;color:#e5e9cc}
.milestone-review[data-focus=choice] .milestone-facts{align-items:center;border-bottom:1px solid #829d7b44;padding:6px 0;gap:20px}
.milestone-review[data-focus=choice] .milestone-boundary{margin:8px 0}
.milestone-notes{margin:8px 0;color:#d3dfcd}.milestone-notes>summary{display:flex;align-items:center;min-height:44px;cursor:pointer;gap:10px;font-size:18px;list-style:none}.milestone-notes>summary::before{content:'＋';color:#b9dba7}.milestone-notes[open]>summary::before{content:'−'}.milestone-notes>summary:focus-visible{outline:2px solid #c6e0a8;outline-offset:2px}
.milestone-notes .review-pages{margin:4px 0 8px}.milestone-review .milestone-notes .reading-text{padding:10px 14px!important;min-height:100px}.milestone-review .milestone-notes .reading-text p{font-size:18px!important;line-height:1.55}
.milestone-notes>small{display:block;margin:4px 0}
.milestone-review[data-focus=choice] footer{justify-content:flex-end;margin-top:8px;padding-top:8px}.milestone-review[data-focus=choice] footer button{min-width:240px;max-width:100%}
